/* Reviewable UI concept. Uses the captured public snapshot, never price/holding simulations. */
'use strict';
const D=window.DESIGN_DATA,M=window.InvestmentUI,E=M.escape,N=M.number,F=M.finite;
const KEY='investment.ui-design.v2';
let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')||{};}catch(_){}
let lang=saved.lang==='en'?'en':'ko',dark=saved.dark===true;
let watch=Array.isArray(saved.watch)?saved.watch.filter(x=>typeof x==='string'):[];
let notes=Array.isArray(saved.notes)?saved.notes.filter(x=>x&&typeof x.text==='string'&&typeof x.at==='string'):[];
let compare=[],page=1,query='',scope='all',sort='ticker',homeList='target',companyTab='overview',newsFilter='all',allocationTab='theme',toastTimer;
const T=(ko,en)=>lang==='en'?en:ko;
const byTicker=new Map(D.rows.map(r=>[r.ticker,r]));
const rows=D.rows.map(r=>({...r,q:M.readAxis(r.record,'Q',D.calcVersion,D.capturedAt),g:M.readAxis(r.record,'G',D.calcVersion,D.capturedAt)}));
const lookup=new Map(rows.map(r=>[r.ticker,r]));
const targets=rows.filter(r=>r.target>0);
const COLORS=['#248f83','#6a97bf','#9294bb','#c2a878','#91b2a3','#7897ab','#bc8794'];
const typeNames={growth:['성장','Growth'],quality:['우량','Quality'],cyclical:['경기민감','Cyclical'],defensive:['경기방어','Defensive']};
const themeNames={ai:['인공지능','AI'],semiconductors:['반도체','Semiconductors'],cloud_software:['클라우드·소프트웨어','Cloud / software'],power_infrastructure:['전력 인프라','Power infrastructure'],defense_aerospace:['항공·방산','Aerospace / defense'],robotics_automation:['로봇·자동화','Robotics / automation'],ecommerce:['전자상거래','E-commerce'],medical_devices:['의료기기','Medical devices'],datacenter_reits:['데이터센터','Data centers'],clean_energy:['청정에너지','Clean energy'],biotech_obesity:['바이오','Biotech'],consumer_brands:['소비재','Consumer brands'],cybersecurity:['보안','Cybersecurity'],fintech_payments:['핀테크','Fintech']};
const industryNames={semiconductors:['반도체','Semiconductors'],semi_equipment:['반도체 장비','Semi equipment'],semiconductor_equipment:['반도체 장비','Semi equipment'],software:['소프트웨어','Software'],software_internet:['소프트웨어·인터넷','Software / internet'],electrical_equipment:['전기 장비','Electrical equipment'],power_equipment:['전력 장비','Power equipment'],industrial_automation:['산업 자동화','Industrial automation'],defense_aerospace:['항공·방산','Aerospace / defense'],medical_devices:['의료기기','Medical devices'],manufacturing_industrial_tech:['제조·산업·기술','Manufacturing / technology'],services_software_health:['서비스·소프트웨어·보건','Services / software / health']};
const tx=(map,key)=>map[key]?map[key][lang==='en'?1:0]:T('분류 확인 필요','Classification unavailable');
const PATHS={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',search:'M20 20l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',portfolio:'M3 7h18v13H3z M8 7V4h8v3 M3 12h18 M10 12v3h4v-3',market:'M4 19V9 M10 19V4 M16 19v-8 M22 19V2',records:'M5 3h14v18H5z M9 8h6 M9 12h6 M9 16h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',arrow:'M5 12h14 M14 7l5 5-5 5',chevron:'M9 5l7 7-7 7',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4z M10 20h4',moon:'M20 15A8 8 0 0 1 9 4a8 8 0 1 0 11 11z',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 1v3 M12 20v3 M1 12h3 M20 12h3 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v6l4 2',shield:'M12 2l8 3v7c0 5-8 10-8 10S4 17 4 12V5z M8 12l3 3 5-6',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',external:'M14 3h7v7 M10 14L21 3 M10 3H3v18h18v-7',plus:'M12 5v14 M5 12h14',close:'M6 6l12 12 M6 18L18 6',compare:'M4 5h6v14H4z M14 5h6v14h-6z',check:'M5 12l4 4L19 6',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 11v6 M12 7v1',chart:'M3 3v18h18 M6 15l4-5 4 3 6-8'};
function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${PATHS[name]||PATHS.grid}"/></svg>`;}
function date(s,full=false){if(typeof s!=='string'||!s.trim())return T('시점 미제공','Date unavailable');const d=new Date(s);if(!Number.isFinite(d.getTime()))return T('시점 미제공','Date unavailable');return new Intl.DateTimeFormat(lang==='en'?'en-GB':'ko-KR',{timeZone:'Asia/Seoul',year:full?'numeric':undefined,month:'2-digit',day:'2-digit',...(full?{hour:'2-digit',minute:'2-digit',hour12:false}:{})}).format(d)+(full?' KST':'');}
function pill(text,tone=''){return `<span class="pill ${tone}">${E(text)}</span>`;}
function btn(text,action,primary=false){return `<button class="btn ${primary?'primary':''}" data-action="${action}">${text}</button>`;}
function link(text,route,cls='inline-link'){return `<a class="${cls}" href="#${E(route)}">${text}${icon('arrow',13)}</a>`;}
function logo(r){return `<span class="logo ${E(r.ticker)}" aria-hidden="true">${E(r.ticker==='MSFT'?'M':r.ticker==='NVDA'?'N':r.ticker==='GOOGL'?'G':r.ticker.slice(0,2))}</span>`;}
function star(r){return `<button class="star" data-star="${E(r.ticker)}" aria-pressed="${watch.includes(r.ticker)}" aria-label="${E(r.ticker+' '+T('관심기업 토글','toggle watchlist'))}">${watch.includes(r.ticker)?'★':'☆'}</button>`;}
function scoreReason(r){const k=M.inputState(r?.record,D.calcVersion,D.capturedAt);return {MISSING:T('자료 미수집','Not collected'),VERSION_MISMATCH:T('버전 불일치','Version mismatch'),STALE:T('갱신 필요','Needs refresh'),INVALID_TIME:T('시점 미확인','Unverified date'),READY:T('산출 불가','Unavailable')}[k];}
function score(v,axis,r){return F(v)?`<span class="score ${axis.toLowerCase()}">${N(v)}<span class="score-track"><i style="width:${v}%"></i></span></span>`:`<span class="na">${scoreReason(r)}</span>`;}
function heading(k,title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${E(k)}</div><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;}
function panel(title,sub,body,action='',foot=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}${foot?`<div class="panel-foot">${foot}</div>`:''}</section>`;}
function save(){try{localStorage.setItem(KEY,JSON.stringify({lang,dark,watch,notes}));return true;}catch(_){toast(T('이 환경에서는 기기 저장을 사용할 수 없습니다. 이번 화면에서만 유지됩니다.','Storage unavailable. Changes last for this session only.'));return false;}}
function toast(msg){const h=document.getElementById('toast');h.textContent=msg;h.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>h.classList.remove('show'),3200);}
function route(){const [name,id]=location.hash.slice(1).split('/');return {name:['today','explore','company','portfolio','market','records','settings'].includes(name)?name:'today',id};}
function shell(){const r=route(),active=r.name==='company'?'explore':r.name;const navs=[['today','home',T('오늘','Today')],['explore','search',T('기업 탐색','Explore')],['portfolio','portfolio',T('내 투자','Portfolio')],['market','market',T('시장·뉴스','Market & news')],['records','records',T('성과·기록','Performance')]];
 document.documentElement.lang=lang;document.body.classList.toggle('dark',dark);
 document.getElementById('sidebar').innerHTML=`<a class="brand" href="#today"><span class="brand-mark">i</span><div><strong>INVESTMENT</strong><small>SYSTEM / PERSONAL</small></div></a><p class="nav-label">WORKSPACE</p><nav aria-label="${T('주요 화면','Main navigation')}">${navs.map(([id,ic,label])=>`<a class="side-link" href="#${id}" ${active===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='explore'?'<b class="nav-count">QGV</b>':''}</a>`).join('')}</nav><div class="side-separator"></div><p class="nav-label">YOUR TOOLS</p><a class="side-link" href="#explore" data-action="watch-view">${icon('grid')}<span>${T('관심기업','Watchlist')}</span></a><a class="side-link" href="#records" data-action="note">${icon('plus')}<span>${T('투자 메모','Investment notes')}</span></a><div class="side-bottom"><div class="sidebar-note"><b>${T('나만의 투자 기준','Your investment framework')}</b><p>${T('기업의 질 · 성장 · 가치<br>판단의 근거를 함께 보세요.','Quality · growth · value<br>Keep the evidence in view.')}</p><a href="#settings">${T('개편 방향 살펴보기','Explore the redesign')} ↗</a></div><a class="side-link" href="#settings" ${active==='settings'?'aria-current="page"':''}>${icon('settings')}<span>${T('설정·데이터','Settings & data')}</span></a><div class="profile"><div class="avatar">P</div><div>${T('개인 워크스페이스','Personal workspace')}<small>READ ONLY · DESIGN V2</small></div></div></div>`;
 document.getElementById('topbar').innerHTML=`<div class="breadcrumb">Workspace <span class="muted">/</span> <b>${r.name==='settings'?T('설정','Settings'):navs.find(x=>x[0]===active)?.[2]||T('오늘','Today')}</b></div><label class="top-search">${icon('search',16)}<input id="global-search" placeholder="${T('기업명 또는 티커 검색','Search company or ticker')}" aria-label="${T('전체 기업 검색','Search all companies')}"><span class="key">/</span></label><div class="top-actions"><span class="preview-label">DESIGN PREVIEW</span><a class="icon-button" href="#settings" aria-label="${T('설정','Settings')}">${icon('settings')}</a><button class="icon-button" data-action="alerts" aria-label="${T('확인할 사항','Review items')}">${icon('bell')}</button><button class="icon-button" data-action="theme" aria-label="${T('화면 테마 전환','Toggle theme')}">${icon(dark?'sun':'moon')}</button><button class="language" data-action="lang" aria-label="${T('영어로 변경','Switch to Korean')}">${lang==='ko'?'EN':'KO'}</button></div>`;
 document.getElementById('mobile-nav').innerHTML=navs.map(([id,ic,label])=>`<a href="#${id}" ${active===id?'aria-current="page"':''}>${icon(ic,19)}<span>${id==='market'?T('시장','Market'):id==='records'?T('기록','Records'):label}</span></a>`).join('');
 document.getElementById('footer').innerHTML=`<span>${T('개인 투자 참고용 · 주문 기능 없음','Personal research · no order execution')} · Investment System</span><span>${T('개편 시안 · 공개 자료 고정본 · 실시간 아님','Design concept · fixed public snapshot · not live')} · ${date(D.asOf)}</span>`;
 document.getElementById('global-search').addEventListener('keydown',e=>{if(e.key==='Enter'){query=e.target.value;scope='all';page=1;if(route().name==='explore')render();else location.hash='explore';}if(e.key==='Escape')e.target.value='';});
}
function metric(label,value,note,progress){return `<div class="metric-card"><div class="metric-label">${label}${icon('info',13)}</div><div class="metric-value mono">${value}</div><div class="metric-note">${note}</div>${F(progress)?`<div class="progress"><span style="width:${progress}%"></span></div>`:''}</div>`;}
function coverage(axis){return D.universeAxes.filter(r=>M.readAxis(r,axis,D.calcVersion,D.capturedAt)!==null).length;}
function snapshotStrip(){return `<div class="status-strip"><div class="left"><span class="dot up"></span><strong>${T('공개 재무 스냅샷','Public financial snapshot')}</strong><span>${T('QGV v2 · 잠정 기준','QGV v2 · provisional')}</span></div><span class="snapshot-time">${T('자료 기준','As of')} ${date(D.asOf,true)}</span>${link(T('출처·상태','Sources & status'),'settings')}</div>`;}
function table(list,{full=false}={}){return `<div class="table-wrap"><table class="${full?'wide-table':'compact-table'}"><thead><tr>${full?`<th class="check-cell">${T('비교','Compare')}</th>`:'<th></th>'}<th>${T('기업','Company')}</th><th>Q <span class="muted">${T('우량성','Quality')}</span></th><th>G <span class="muted">${T('성장성','Growth')}</span></th><th>V <span class="muted">${T('가치','Value')}</span></th>${full?`<th>${T('수집 시각','Acquired')}</th>`:''}<th></th></tr></thead><tbody>${list.length?list.map(r=>`<tr>${full?`<td><input type="checkbox" data-compare="${E(r.ticker)}" aria-label="${E(r.ticker+' '+T('비교 선택','compare'))}" ${compare.includes(r.ticker)?'checked':''}></td>`:`<td>${star(r)}</td>`}<td><a class="company-cell" href="#company/${encodeURIComponent(r.ticker)}">${logo(r)}<div><b>${E(r.ticker)}</b><small>${E(r.name)}</small></div></a></td><td>${score(r.q,'q',r)}</td><td>${score(r.g,'g',r)}</td><td><span class="na">${T('가격 필요','Needs price')}</span></td>${full?`<td class="small muted">${r.record.acquired_at?date(r.record.acquired_at):'—'}</td>`:''}<td>${full?star(r):`<a href="#company/${encodeURIComponent(r.ticker)}" aria-label="${E(r.ticker+' '+T('상세','details'))}">${icon('chevron',14)}</a>`}</td></tr>`).join(''):`<tr><td colspan="7"><div class="empty">${T('조건에 맞는 기업이 없습니다. 검색어나 필터를 바꿔보세요.','No matches. Try another search or filter.')}</div></td></tr>`}</tbody></table></div>`;}
function scatter(list){const points=list.filter(r=>F(r.q)&&F(r.g)),W=620,H=270,x=q=>48+q*5.35,y=g=>224-g*1.85;
return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${T('기준기업 Q 우량성, G 성장성 산점도. 아래 표에서 정확한 값을 확인할 수 있습니다.','Q quality versus G growth. Exact values are in the company table.')}" ><rect x="315.5" y="39" width="267.5" height="92.5" fill="var(--soft)" opacity=".75"/>${[0,25,50,75,100].map(v=>`<line class="grid" x1="48" y1="${y(v)}" x2="583" y2="${y(v)}"/><text x="30" y="${y(v)+3}" text-anchor="end">${v}</text><text x="${x(v)}" y="244" text-anchor="middle">${v}</text>`).join('')}<line class="grid" x1="315.5" y1="39" x2="315.5" y2="224"/><text x="50" y="18">G · ${T('성장성','Growth')}</text><text x="583" y="263" text-anchor="end">Q · ${T('우량성','Quality')}</text>${points.map(r=>`<a href="#company/${encodeURIComponent(r.ticker)}" aria-label="${E(r.ticker)} Q ${N(r.q)} G ${N(r.g)}"><circle class="point" cx="${x(r.q)}" cy="${y(r.g)}" r="${r.ticker==='NVDA'?6:4.5}" fill="${r.ticker==='NVDA'?'#248f83':'#709ba8'}" opacity=".85"><title>${E(r.ticker)} · Q ${N(r.q)} / G ${N(r.g)}</title></circle>${['NVDA','MSFT','ASML','INTC','QCOM','AMD'].includes(r.ticker)?`<text class="plot-label" x="${x(r.q)+8}" y="${y(r.g)+(r.ticker==='MSFT'?16:-7)}">${E(r.ticker)}</text>`:''}</a>`).join('')}</svg>`;}
function donut(){let offset=0;return `<svg class="donut" viewBox="0 0 160 160" role="img" aria-label="${T('목표 v0: 반도체 장비 30%, AI·반도체 25%, 빅테크 20%, 기타산업 25%','Target v0 allocation: semiconductor equipment 30%, AI / semiconductors 25%, Big Tech 20%, other industrials 25%')}"><circle cx="80" cy="80" r="60" fill="none" stroke="var(--line)" stroke-width="16"/>${D.themes.map((t,i)=>{const n=t.target_units/100,markup=`<circle cx="80" cy="80" r="60" fill="none" stroke="${COLORS[i]}" stroke-width="16" pathLength="100" stroke-dasharray="${n-.8} ${100-n+.8}" stroke-dashoffset="${-offset}" transform="rotate(-90 80 80)"/>`;offset+=n;return markup;}).join('')}<text x="80" y="78" text-anchor="middle" font-size="26" font-weight="650">19</text><text x="80" y="97" text-anchor="middle" font-size="9">${T('기준 포트폴리오','REFERENCE TARGET')}</text></svg>`;}
function allocation(){return `<div class="allocation">${donut()}<div class="legend">${D.themes.map((t,i)=>`<div class="legend-row"><span class="swatch" style="--color:${COLORS[i]}"></span>${E(lang==='en'?t.label_en:t.label)}<strong>${t.target_units/100}%</strong></div>`).join('')}</div></div>`;}
function newsItems(items){return items.length?items.map(a=>{const href=M.safeUrl(a.url);return `<article class="news-item"><span class="news-symbol">${E(a.ticker)}</span><div>${href?`<a href="${E(href)}" target="_blank" rel="noopener noreferrer">`:''}<h3>${E(a.title)}</h3>${href?'</a>':''}<p>${pill(a.kind==='filing'?T('공시·확인','Filed disclosure'):T('뉴스·신호','News signal'),a.kind==='filing'?'green':'blue')}<span>${a.occurrence==='NEW'?T('신규','New'):T('기존','Existing')}</span><span>${E(a.source)} · ${date(a.at,true)}</span></p></div>${href?`<a class="arrow" href="${E(href)}" target="_blank" rel="noopener noreferrer" aria-label="${T('원문 열기','Open source')}">${icon('external',13)}</a>`:''}</article>`;}).join(''):`<div class="empty">${T('해당하는 수집 기록이 없습니다.','No captured records match this selection.')}</div>`;}
function today(){const mainOrder=['NVDA','MSFT','ASML','GOOGL','AMZN','AMD'];const list=homeList==='watch'?rows.filter(r=>watch.includes(r.ticker)).slice(0,6):mainOrder.map(t=>lookup.get(t)).filter(Boolean);
return heading('YOUR DAILY WORKSPACE',T('오늘의 투자','Your investment day'),T('변화를 살펴보고, 근거를 확인하고, 판단을 기록하세요.','Review the changes. Read the evidence. Record your thinking.'),btn(icon('plus',14)+T('관심기업 추가','Add to watchlist'),'add-watch',true))+snapshotStrip()+
`<div class="overview-metrics">${metric(T('기준 포트폴리오','Reference portfolio'),`19<small>${T('기업','companies')}</small>`,T('TARGET v0 · 실제 보유와 별도','TARGET v0 · separate from holdings'))}${metric(T('Q 산출 범위','Q coverage'),`${coverage('Q')}<small>/ ${D.universeCount}</small>`,T('미국 Universe · 공개 게시본','US universe · published snapshot'),coverage('Q')/D.universeCount*100)}${metric(T('G 산출 범위','G coverage'),`${coverage('G')}<small>/ ${D.universeCount}</small>`,T('같은 계산 버전의 유효 자료','Valid inputs of the same version'),coverage('G')/D.universeCount*100)}${metric(T('내 관심기업','My watchlist'),`${watch.length}<small>${T('기업','companies')}</small>`,T('별표로 모아보기 · 시안 전용','Save with a star · preview only'))}</div>`+
`<div class="dashboard"><div class="column">${panel(T('기업 한눈에 보기','Companies at a glance'),T('Q·G는 100점 척도 · 높을수록 해당 특성이 강합니다.','Q and G use a 0–100 scale. Higher values indicate stronger traits.'),`<div class="tabs"><button data-home-tab="target" aria-pressed="${homeList==='target'}">${T('기준기업','Reference companies')} <span class="muted">19</span></button><button data-home-tab="watch" aria-pressed="${homeList==='watch'}">${T('내 관심','My watchlist')} <span class="muted">${watch.length}</span></button></div>${table(list)}`,link(T('전체 탐색','Explore all'),'explore'),`<span>${T('표시 순서는 추천 순위가 아닙니다. V·총점은 가격 연결 후 확인합니다.','Display order is not a recommendation. V and total scores need price inputs.')}</span>`)}
${panel(T('우량성과 성장성의 위치','Quality meets growth'),T('기준기업 19개 중 유효한 Q·G가 있는 기업만 표시','Only reference companies with valid Q and G inputs are shown'),`<div class="panel-body">${scatter(targets)}<div class="chart-legend"><span><i class="swatch" style="--color:#248f83"></i>${T('점을 선택하면 기업 상세','Select a point to explore')}</span><span>${T('시장수익률·매수 신호 아님','Not returns or a buy signal')}</span></div></div>`,pill('Q × G'))}</div><div class="column">`+
`<section class="panel connection-panel"><span class="connection-icon">${icon('portfolio',25)}</span><div class="eyebrow">MY PORTFOLIO</div><h2>${T('내 투자와 연결하세요','Bring your portfolio into view')}</h2><p>${T('보유를 연결하면 평가금액, 목표와의 차이,<br>확인할 위험을 한곳에서 볼 수 있습니다.','Connect holdings to see value, allocation gaps and risks in one place.')}</p>${btn(T('보유 연결 안내','Connect holdings')+icon('arrow',14),'connect')}<div class="tiny-steps"><span>01 ${T('보유 입력','Holdings')}</span><span>02 ${T('시세 연결','Quotes')}</span><span>03 ${T('차이 확인','Review gaps')}</span></div></section>`+
panel(T('기준 배분','Reference allocation'),T('TARGET v0 · 출발점·비교 기준','TARGET v0 · starting point & benchmark'),`<div class="panel-body">${allocation()}<div class="notice-box">${T('반도체 묶음 <strong>55%</strong> · v1 업종 상한 40%와 비교할 때 초과','Semiconductor group <strong>55%</strong> · above the 40% v1 limit')}</div></div>`,link(T('내 투자','Portfolio'),'portfolio'))+
panel(T('최근 공시·뉴스','Recent filings & news'),T('원문과 확인 여부를 함께 봅니다.','Read the source and its evidence status.'),`<div class="panel-body">${newsItems(D.articles.slice(0,3))}</div>`,link(T('전체','All'),'market'))+`</div></div>`;}
function explore(){const filtered=M.filter(rows,{query,scope,sort,watch}),pages=Math.max(1,Math.ceil(filtered.length/15));page=Math.min(page,pages);return heading('COMPANY EXPLORER',T('기업 탐색','Explore companies'),T('기업을 찾고, 비교하고, 나만의 관심 목록을 만드세요.','Find, compare and build your own watchlist.'),btn(icon('compare',14)+T('기업 비교','Compare'),'compare'))+`<section class="panel"><div class="filters"><input id="company-search" type="search" value="${E(query)}" placeholder="${T('티커 · 영문명 · 한국어 이름','Ticker · company · Korean alias')}" aria-label="${T('기업 검색','Company search')}"><select id="company-sort" aria-label="${T('정렬','Sort')}">${[['ticker',T('티커 순','Ticker A–Z')],['q',T('Q 높은 순','Quality: high to low')],['g',T('G 높은 순','Growth: high to low')]].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select><div class="filter-pills">${[['all',T('전체','All')],['target',T('기준 19기업','Reference 19')],['watch',T('내 관심','Watchlist')],['ready',T('Q·G 있음','Q & G available')]].map(([v,l])=>`<button data-scope="${v}" class="${scope===v?'active':''}" aria-pressed="${scope===v}">${l}</button>`).join('')}</div></div><div class="table-count" id="explorer-count"><span><b>${filtered.length}</b> ${T('개 기업','companies')} ${scope==='all'?`· ${T('미국 504 + 한국·일본 2','US 504 + KR / JP 2')}`:''}</span><span>${T('최대 3개 비교','Compare up to 3')}</span></div><div id="explorer-results">${table(filtered.slice((page-1)*15,page*15),{full:true})}</div><div class="pages" id="explorer-pages"><span>${page} / ${pages}</span><button data-page="-1" ${page===1?'disabled':''}>${T('이전','Previous')}</button><button data-page="1" ${page===pages?'disabled':''}>${T('다음','Next')}</button></div></section><div class="notice-box">${T('이 시안의 데이터는 열람 시점의 공개 스냅샷입니다. 자료 없음·계산 버전 불일치·7일 초과 자료는 Q·G를 비워 둡니다. 가격이나 총점을 임의로 채우지 않습니다.','This is a captured public snapshot. Missing, version-mismatched and over-7-day inputs show no Q or G. Prices and totals are never invented.')}</div>`;}
function classifications(r){const ind=r.classification?.industry,theme=r.classification?.themes;const types=Object.entries(r.types||{}).filter(([k,v])=>F(v)&&v>=.3&&typeNames[k]);const themes=Object.entries(theme?.memberships||{}).filter(([k,v])=>v.member===true);return `<div class="classification"><div class="axis"><label>Investment Type <span>${T('투자 유형','')}</span></label>${types.length?types.map(([k])=>pill(tx(typeNames,k),'green')).join(''):pill(T('미확인','Unconfirmed'))}</div><div class="axis"><label>${T('산업 분류','Industry')} · SIC</label>${ind?.state==='LIVE'?pill(tx(industryNames,ind.subgroup||ind.group),'blue'):pill(T('미확인','Unconfirmed'))}</div><div class="axis"><label>Strategy Theme <span>${T('전략 테마','')}</span></label>${themes.length?themes.slice(0,3).map(([k])=>pill(tx(themeNames,k))).join('')+(themes.length>3?pill('+'+(themes.length-3)):''):pill(T('미확인','Unconfirmed'))}</div></div>`;}
function lineChart(r){const items=r.history.filter(v=>F(v.value)&&v.fiscal_year_end).sort((a,b)=>a.fiscal_year_end.localeCompare(b.fiscal_year_end));if(!items.length)return `<div class="empty">${T('이 기업의 연간 영업이익률 기록이 없습니다.','No annual operating margin history captured for this company.')}</div>`;const lo=Math.min(0,...items.map(v=>v.value*100)),hi=Math.max(10,...items.map(v=>v.value*100))*1.15,dx=i=>50+i*500/Math.max(1,items.length-1),dy=v=>205-(v-lo)/(hi-lo)*165,path=items.map((v,i)=>`${i?'L':'M'} ${dx(i)} ${dy(v.value*100)}`).join(' ');return `<svg class="chart" viewBox="0 0 600 250" role="img" aria-label="${E(r.ticker+' '+T('연간 영업이익률 추이','annual operating margin history'))}">${[0,1,2,3,4].map(i=>{const v=lo+(hi-lo)*i/4;return `<line class="grid" x1="50" x2="550" y1="${dy(v)}" y2="${dy(v)}"/><text x="37" y="${dy(v)+3}" text-anchor="end">${N(v,0)}%</text>`;}).join('')}<path d="${path} L550 205 L50 205 Z" fill="var(--soft)"/><path d="${path}" fill="none" stroke="var(--accent)" stroke-width="2.5"/>${items.map((v,i)=>`<circle cx="${dx(i)}" cy="${dy(v.value*100)}" r="4" fill="var(--surface)" stroke="var(--accent)" stroke-width="2"><title>FY${v.fiscal_year_end.slice(0,4)}: ${N(v.value*100)}%</title></circle><text x="${dx(i)}" y="${dy(v.value*100)-14}" text-anchor="middle">${N(v.value*100)}%</text><text x="${dx(i)}" y="234" text-anchor="middle">FY${v.fiscal_year_end.slice(0,4)}</text>`).join('')}</svg><div class="source-line">${T('SEC 공시 기반 · 연간 영업이익률 · 주가 차트 아님','SEC filings · annual operating margin · not a price chart')}</div>`;}
function financialFacts(r){const m=r.record.metrics||{};return `<div class="detail-facts">${[[T('투하자본수익률 ROIC','Return on invested capital'),m.roic,100,'%'],[T('3년 매출 성장률','3Y revenue CAGR'),m.revenue_cagr_3y,100,'%'],[T('최근 12개월 매출 성장','TTM revenue growth'),m.revenue_ttm_growth,100,'%'],[T('순부채 / EBITDA','Net debt / EBITDA'),m.net_debt_to_ebitda,1,'×']].map(([l,v,mul,suf])=>`<div class="fact"><label>${l}</label><b>${F(v)?N(v*mul)+suf:'—'}</b></div>`).join('')}</div>`;}
function factorRows(r,axis){const factorLabels={q_profitability:['수익성','Profitability'],q_moat_proxy:['해자 대리 지표','Moat proxy'],q_earnings_quality:['이익의 질','Earnings quality'],q_financial_safety:['재무 안전','Financial safety'],q_capital_allocation:['자본 배분','Capital allocation'],g_revenue_growth:['매출 성장','Revenue growth'],g_per_share_growth:['주당 이익·FCF 성장','Per-share growth'],g_growth_efficiency:['성장 효율','Growth efficiency'],g_consistency:['성장 일관성','Growth consistency'],g_recent_acceleration:['최근 가속','Acceleration']};const valid=F(r[axis.toLowerCase()]);return Object.entries(factorLabels).filter(([k])=>k.startsWith(axis.toLowerCase()+'_')).map(([k,v])=>{const score=valid?r.record.factors?.[k]:null;return `<div class="factor-row"><span>${E(v[lang==='en'?1:0])}</span><div class="progress"><span style="width:${F(score)?score:0}%"></span></div><b>${N(score)}</b></div>`;}).join('');}
function sourceNote(r){const state=M.inputState(r.record,D.calcVersion,D.capturedAt),why={MISSING:T('원자료 미수집 또는 산출 불가','Source missing or unavailable'),VERSION_MISMATCH:T('현재 계산 버전과 다른 자료 · 점수 보류','Calculation version mismatch · scores withheld'),STALE:T('수집 후 7일 초과 · 점수 보류','Over seven days old · scores withheld'),INVALID_TIME:T('수집 시점 확인 불가 · 점수 보류','Acquisition time invalid · scores withheld')};return (state!=='READY'?'<div class="notice-box">'+E(why[state])+'</div>':'')+ `<div class="source-line">${T('SEC 재무 자료','SEC financial data')} · ${T('회계연도 종료','Fiscal year end')} ${E(r.record.fiscal_year_end||'—')}<br>${T('수집','Acquired')} ${date(r.record.acquired_at,true)} · ${T('개별 기업 자료 기준','Company-specific capture')}<br>${T('다른 수집 시점·비교 모집단에 따라 점수가 달라질 수 있습니다.','Scores may differ with acquisition time and comparison universe.')}</div>`;}
function company(ticker){let r=lookup.get(ticker);if(!r)return heading('COMPANY',T('기업을 찾을 수 없습니다','Company not found'),T('검색 화면에서 다시 선택해 주세요.','Choose a company from Explore.'),link(T('기업 탐색','Explore'),'explore','btn'));
 const tabs=[['overview',T('종합','Overview')],['financial',T('재무·QGV','Financials & QGV')],['price',T('가격·가치','Price & value')],['news',T('공시·뉴스','Filings & news')]];
 let content='';
 if(companyTab==='overview'||companyTab==='financial')content=`<div class="two-grid">${panel(T('기업의 질과 성장','Quality & growth'),T('QGV v2 · 공개 재무 결과','QGV v2 · public financial results'),`<div class="panel-body"><div class="qg-cards">${[['Q',T('우량성','Quality'),r.q],['G',T('성장성','Growth'),r.g],['V',T('가치','Value'),null]].map(([a,l,v])=>`<div class="qg-card"><label>${a} · ${l}</label><div class="big mono">${N(v)}${F(v)?'<small> / 100</small>':''}</div><small>${a==='V'?T('가격 연결 필요','Price required'):F(v)?T('공식 산출값','Published score'):scoreReason(r)}</small></div>`).join('')}</div><div class="notice-box">${T('<strong>총점은 가격 연결 후 확인합니다.</strong><br>Q·G와 V의 결측을 구분하며 임의의 평균 점수를 만들지 않습니다.','<strong>Connect price inputs to view the total.</strong><br>Missing axes remain separate; no substitute total is created.')}</div>${financialFacts(r)}${sourceNote(r)}</div>`,pill(T('잠정 기준','Provisional'),'amber'))}
${panel(T('영업이익률 추이','Operating margin'),T('이익을 얼마나 안정적으로 남기는가','How consistently does the business earn a profit?'),`<div class="panel-body">${lineChart(r)}<div class="notice-box">${T('공식 연간 자료를 그대로 표시합니다. 빈 연도는 추정하지 않습니다.','Published annual observations only. Missing years are not estimated.')}</div></div>`,pill('FY · %'))}</div>`+
`<div class="two-grid section-gap">${panel('Q · '+T('우량성 구성','Quality factors'),T('원자료가 아닌 계산된 요인 점수','Calculated factor scores, not raw financial inputs'),`<div class="panel-body">${factorRows(r,'Q')}</div>`)}${panel('G · '+T('성장성 구성','Growth factors'),T('산출된 요인만 표시','Only available factors are shown'),`<div class="panel-body">${factorRows(r,'G')}</div>`)}</div>`;
 if(companyTab==='price')content=`<div class="two-grid">${panel(T('가격 차트','Price chart'),T('현재가 · 캔들 · 거래량 · 고점 대비 하락률','Price · candles · volume · drawdown'),`<div class="empty">${icon('chart',40)}<h3>${T('시세를 연결하면 분석이 이어집니다','Connect prices to continue')}</h3><p>${T('현재 이 시안에는 가격 이력이 없습니다.<br>임의 가격과 가상의 캔들을 표시하지 않습니다.','This preview contains no price history.<br>No simulated prices or candles are displayed.')}</p>${btn(T('시세 연결 안내','Quote connection guide'),'connect',true)}</div>`)}${panel(T('가치·기대·위험','Value, expectations & risk'),T('가격과 재무 입력을 함께 확인','Combine price and financial inputs'),`<div class="panel-body"><div class="text-list">${[[T('상대가치','Relative value'),T('산업·역사적 위치와 V 백분위','Industry / historical context and V percentile')],['DCF · Reverse DCF',T('참고 가치 범위와 가격에 반영된 기대','Reference value range and implied expectations')],['VMR',T('변동성 · ATR · 베타 · 기업별 재검토 조건','Volatility · ATR · beta · review triggers')]].map(([a,b])=>`<div><b>${a}</b><p>${b}</p>${pill(T('가격 입력 대기','Awaiting price inputs'))}</div>`).join('')}</div><p class="footnote">${T('차트 고도화·패턴 탐지는 별도 승인·검증 후 연결합니다.','Advanced charts and pattern detection require their existing approval and validation steps.')}</p></div>`)}</div>`;
 if(companyTab==='news')content=panel(T('공시와 뉴스의 근거','Evidence behind the news'),T('뉴스는 신호로, 공시는 확인 가능한 근거로 구분합니다.','News signals and filed evidence are kept distinct.'),`<div class="panel-body">${newsItems(D.articles.filter(a=>a.ticker===r.ticker))}</div>`);
 return `<div class="page-heading"><div><div class="eyebrow"><a href="#explore">← ${T('기업 탐색','EXPLORE COMPANIES')}</a></div><div class="company-heading">${logo(r)}<div><h1>${E(r.ticker)}</h1><p>${E(r.name)} · ${E(lang==='en'?r.aboutEn:r.about)}</p></div></div></div><div class="head-actions">${star(r)}<button class="btn" data-add-compare="${E(r.ticker)}">${icon('compare',14)}${T('비교','Compare')}</button>${btn(icon('plus',14)+T('메모','Note'),'note')}</div></div>${classifications(r)}<div class="tabs company-nav">${tabs.map(([id,l])=>`<button data-company-tab="${id}" aria-pressed="${companyTab===id}">${l}</button>`).join('')}</div>${content}`;
}
function exposure(){if(allocationTab==='theme')return allocation();
 if(allocationTab==='industry'){const groups={};for(const r of targets){const i=r.classification?.industry,key=i?.state==='LIVE'?(i.subgroup||i.group):'unknown';groups[key]=(groups[key]||0)+r.target;}return `<div class="axis-bars">${Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([k,v],i)=>`<div style="--color:${COLORS[i%COLORS.length]}"><div class="axis-bar-label"><span>${k==='unknown'?T('미분류','Unclassified'):tx(industryNames,k)}</span><b>${N(v)}%</b></div><div class="progress"><span style="width:${v}%"></span></div></div>`).join('')}</div><p class="footnote">${T('공개 SIC 기반 분류 · GICS로 간주하지 않습니다.','Published SIC grouping · not a GICS classification.')}</p>`;}
 const sums=Object.keys(typeNames).map(k=>[k,targets.filter(r=>F(r.types[k])&&r.types[k]>=.3).reduce((s,r)=>s+r.target,0)]);return `<div class="axis-bars">${sums.map(([k,v],i)=>`<div style="--color:${COLORS[i]}"><div class="axis-bar-label"><span>${tx(typeNames,k)}</span><b>${N(v)}%</b></div><div class="progress"><span style="width:${v}%"></span></div></div>`).join('')}</div><div class="notice-box">${T('유형 소속도 0.3 이상인 공개 항목의 참고 노출입니다. 한 기업이 여러 유형에 포함되므로 합계가 100%가 될 필요는 없습니다. 미확인 유형은 추정하지 않습니다.','Reference exposure to published memberships ≥ 0.3. A company may have multiple types; totals need not equal 100%. Unknown memberships are not inferred.')}</div>`;}
